import {usePluginStore,useWatchEvent} from '@/hooks/plugin';import {drawTripleRing,loadTripleRingFont,tripleRingKey} from '@/triple-ring';
export default function(name:string){const plugin=usePluginStore(),ActionID=window.argv[3].plugin.uuid+'.'+name,items=new Map<string,any>();function stop(context:string){plugin.Unterval(ActionID+context);items.delete(context);}async function start(context:string){stop(context);const st={canvas:document.createElement('canvas'),ready:false,last:'',busy:false};items.set(context,st);try{await loadTripleRingFont();if(items.get(context)!==st)return;st.ready=true;draw(context,true);plugin.Interval(ActionID+context,50,()=>draw(context));}catch(e){console.error(JSON.stringify({event:'triple_ring_font_error',error:String(e)}));}}function draw(context:string,force=false){const st=items.get(context),a=plugin.getAction(context);if(!st?.ready||!a||st.busy)return;const d=new Date(),s=a.settings as any,key=tripleRingKey(s,d);if(!force&&st.last===key)return;const canvas=drawTripleRing(st.canvas,s,d);if(s.transport==='binary'){st.busy=true;canvas.toBlob(async blob=>{try{if(blob&&items.get(context)===st){a.setImageBlob(await blob.arrayBuffer(),'image/png');st.last=key;}}finally{st.busy=false;}},'image/png');}else try{a.setImage(canvas.toDataURL('image/jpeg',.93));st.last=key;}catch(e){console.error(JSON.stringify({event:'triple_ring_send_error',error:String(e)}));}}useWatchEvent('action',{ActionID,willAppear:({context})=>start(context),willDisappear:({context})=>stop(context),didReceiveSettings:({context})=>draw(context,true)});}
